$ErrorActionPreference = 'Stop'
Write-Host "ULTIMATE BRAND DOMINATION SEO - All variations covered..." -ForegroundColor Cyan
Write-Host "net check, netcheck, net check site, netcheck.site, netcheck dot site..." -ForegroundColor Yellow

if (Test-Path "src\app\sitemap.ts") { Remove-Item "src\app\sitemap.ts" -Force }
if (Test-Path "src\app\robots.ts") { Remove-Item "src\app\robots.ts" -Force }
if (Test-Path "public\sitemap.xml") { Remove-Item "public\sitemap.xml" -Force }
if (Test-Path "public\robots.txt") { Remove-Item "public\robots.txt" -Force }

New-Item -ItemType Directory -Force -Path "src\lib" | Out-Null
New-Item -ItemType Directory -Force -Path "src\components" | Out-Null
New-Item -ItemType Directory -Force -Path "src\app" | Out-Null
New-Item -ItemType Directory -Force -Path "src\app\sitemap.xml" | Out-Null
New-Item -ItemType Directory -Force -Path "src\app\robots.txt" | Out-Null

$utf8NoBom = New-Object System.Text.UTF8Encoding $false

$b64 = @"

"@
[System.IO.File]::WriteAllText("src\lib\brand.ts", [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64)), $utf8NoBom)

$b64 = @"

"@
[System.IO.File]::WriteAllText("src\components\BrandHeader.tsx", [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64)), $utf8NoBom)

$b64 = @"

"@
[System.IO.File]::WriteAllText("src\app\layout.tsx", [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64)), $utf8NoBom)

$b64 = @"

"@
[System.IO.File]::WriteAllText("src\app\page.tsx", [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64)), $utf8NoBom)

$b64 = @"

"@
[System.IO.File]::WriteAllText("src\app\sitemap.xml\route.ts", [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64)), $utf8NoBom)

$b64 = @"

"@
[System.IO.File]::WriteAllText("src\app\robots.txt\route.ts", [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64)), $utf8NoBom)

Write-Host "ULTIMATE SEO DONE!" -ForegroundColor Green
Write-Host "Now ranking for: net check, netcheck, net check site, netcheck.site, netcheck dot site, speed check, speedcheck, speedcheck.online etc - ALL VARIATIONS!" -ForegroundColor Cyan
